-- ════════════════════════════════════════════════════════
-- 315 — Le lexique passe de 20 à 56 termes
-- ────────────────────────────────────────────────────────
-- CE QU'ON A TROUVÉ. L'audit de contenu (31 octobre 2026) place le lexique parmi les zones maigres : 20 termes pour
-- un métier qui en compte des centaines. Ce lot ajoute 36 termes que la prose de l'atlas emploie ou que le lecteur
-- cherchera : fabrication (fermentation, despalillo, casa de tabaco, tripe longue, chaveta), formes (robusto,
-- lancero, torpedo, Churchill, calibre), culture (tapado, plein soleil, moho azul), conservation (humidor,
-- hygromètre, cèdre, plume, régulateur d'humidité), dégustation (tirage, cendre, rétro-olfaction, coupe, tiers) et
-- marché (éditions régionale et limitée, bande de garantie).
-- 1. Chaque définition tient en deux phrases et ne cite aucun prix, aucune marque en vente, aucune parole rapportée.
--    Les chiffres sont des ordres de grandeur d'usage (humidité 65-72 %, calibre en 64e de pouce) et les dires de
--    Habanos sont attribués (édition limitée).
-- 2. Les variantes sont des chaînes littérales françaises (la détection se fait sur le français). On évite les mots
--    trop courants (« tête », « pied », « corona ») qui allumeraient une glose au mauvais endroit.
-- 3. Traductions en cinq langues, scellées « machine » dans translation_status.
-- ════════════════════════════════════════════════════════

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'fermentation', 'atelier', 'fermentation|fermentations', 'Fermentation', 'L''étape où les feuilles, empilées en pilón, chauffent d''elles-mêmes. Elles y perdent de leur amertume et de leur ammoniaque ; elle dure de quelques semaines à plusieurs mois selon la feuille.', 'Fermentation', 'The stage where leaves stacked in a pilón heat up on their own. They lose bitterness and ammonia there; it lasts from a few weeks to several months depending on the leaf.', 'Fermentación', 'La etapa en que las hojas apiladas en un pilón se calientan solas. Pierden amargor y amoníaco; dura de unas semanas a varios meses según la hoja.', 'Fermentation', 'Die Phase, in der sich die zu einem Pilón gestapelten Blätter von selbst erwärmen. Sie verlieren dabei Bitterkeit und Ammoniak; je nach Blatt dauert sie einige Wochen bis mehrere Monate.', '发酵', '把烟叶堆成 pilón 后，叶堆自行升温的阶段。烟叶在其中褪去苦味和氨味；视烟叶而定，持续数周到数月。', 'التخمير', 'المرحلة التي تسخن فيها الأوراق المكدّسة في كومة «بيلون» من تلقاء نفسها. تفقد خلالها شيئًا من مرارتها ومن الأمونيا؛ وتمتد من أسابيع قليلة إلى عدة شهور بحسب الورقة.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'fermentation');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'despalillo', 'atelier', 'despalillo|écôtage|écotage', 'Despalillo', 'Le retrait de la nervure centrale de la feuille avant le roulage, à la main ou à l''outil. Sans lui, la côte durcirait le cigare et gênerait le tirage.', 'Despalillo', 'Removing the central rib of the leaf before rolling, by hand or with a tool. Without it the rib would harden the cigar and hamper the draw.', 'Despalillo', 'Quitar la vena central de la hoja antes de liar, a mano o con una herramienta. Sin ello, la vena endurecería el puro y estorbaría el tiro.', 'Despalillo', 'Das Entfernen der Mittelrippe des Blattes vor dem Rollen, von Hand oder mit einem Werkzeug. Ohne sie würde die Rippe die Zigarre verhärten und den Zug behindern.', '去梗', '卷制前去掉烟叶的中央主脉，用手或工具完成。若不去梗，叶脉会使雪茄变硬，影响抽吸的顺畅。', 'إزالة العرق', 'نزع العرق المركزي من الورقة قبل اللفّ، يدويًا أو بأداة. وبدونه يقسو العرق على السيجار ويعيق السحب.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'despalillo');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'casa-de-tabaco', 'atelier', 'casa de tabaco|casas de tabaco|séchoir', 'Casa de tabaco', 'La grange où l''on suspend les feuilles récoltées pour le séchage à l''air. Elle est haute, ouverte aux courants d''air, et son toit de palmes est un trait du paysage de Vuelta Abajo.', 'Casa de tabaco', 'The barn where harvested leaves are hung to air-cure. It is tall, open to drafts, and its palm-thatched roof is a feature of the Vuelta Abajo landscape.', 'Casa de tabaco', 'El granero donde se cuelgan las hojas cosechadas para curarlas al aire. Es alto, abierto a las corrientes de aire, y su techo de guano es un rasgo del paisaje de Vuelta Abajo.', 'Casa de tabaco', 'Die Scheune, in der die geernteten Blätter zur Lufttrocknung aufgehängt werden. Sie ist hoch, für Durchzug offen, und ihr Palmdach prägt die Landschaft von Vuelta Abajo.', '烟叶晾房', '悬挂收获烟叶进行风干的高大棚屋，通风敞开，棕榈叶屋顶是比尔塔阿瓦霍（Vuelta Abajo）风景的一部分。', 'كاسا دي تاباكو', 'الحظيرة التي تُعلَّق فيها الأوراق المحصودة لتجفّ في الهواء. وهي عالية ومفتوحة للتيارات الهوائية، وسقفها من سعف النخيل من معالم منظر فويلتا أباخو.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'casa-de-tabaco');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'tripe-longue', 'assemblage', 'tripe longue|tripa larga|long filler', 'Tripe longue', 'Une tripe faite de feuilles entières ou de longs morceaux qui courent d''un bout à l''autre du cigare. La tripe courte (short filler) est faite de fragments découpés ; la tripe mixte mêle les deux.', 'Long filler', 'A filler made of whole leaves or long pieces running from one end of the cigar to the other. Short filler is made of cut fragments; mixed filler combines the two.', 'Tripa larga', 'Una tripa hecha de hojas enteras o de trozos largos que recorren el puro de un extremo a otro. La tripa corta se hace con fragmentos cortados; la mixta combina ambas.', 'Langfüller', 'Ein Einlage aus ganzen Blättern oder langen Stücken, die von einem Ende der Zigarre zum anderen laufen. Kurzfüller besteht aus geschnittenen Fragmenten; Mischfüller kombiniert beides.', '长叶芯', '由整片烟叶或贯穿雪茄两端的长条烟叶构成的叶芯。短叶芯由切碎的碎片构成，混合叶芯则两者兼有。', 'الحشوة الطويلة', 'حشوة مصنوعة من أوراق كاملة أو قطع طويلة تمتد من طرف السيجار إلى طرفه الآخر. أما الحشوة القصيرة فمن شظايا مقطّعة، والمختلطة تجمع بين النوعين.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'tripe-longue');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'hecho-a-mano', 'atelier', 'hecho a mano|roulé à la main|roulés à la main|fait main', 'Hecho a mano', '« Fait à la main » en espagnol : la mention des cigares roulés par un torcedor, sans machine. Elle ne dit rien, seule, de la qualité du tabac.', 'Hecho a mano', 'Spanish for "made by hand": the mention for cigars rolled by a torcedor, without a machine. On its own it says nothing about the quality of the tobacco.', 'Hecho a mano', '«Hecho a mano»: la mención de los puros liados por un torcedor, sin máquina. Por sí sola no dice nada de la calidad del tabaco.', 'Hecho a mano', 'Spanisch für „von Hand gemacht“: der Hinweis auf Zigarren, die ein Torcedor ohne Maschine rollt. Für sich allein sagt er nichts über die Qualität des Tabaks.', '手工制作', '西班牙语“手工制作”：指由卷烟师（torcedor）不用机器卷成的雪茄。仅凭这一标注，说明不了烟叶的品质。', 'هيتشو آ مانو', 'بالإسبانية «مصنوع باليد»: عبارة تدل على سيجار لفّه «تورسيدور» دون آلة. وهي وحدها لا تقول شيئًا عن جودة التبغ.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'hecho-a-mano');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'chaveta', 'atelier', 'chaveta', 'Chaveta', 'Le couteau en demi-lune du torcedor. Il découpe la cape dans la feuille ; c''est le seul outil, avec la colle végétale, que l''ouvrier garde à portée de main.', 'Chaveta', 'The torcedor''s half-moon knife. It cuts the wrapper from the leaf; apart from the vegetable glue, it is the one tool the roller keeps within reach.', 'Chaveta', 'El cuchillo en media luna del torcedor. Corta la capa de la hoja; junto con el pegamento vegetal, es la única herramienta que el liador tiene a mano.', 'Chaveta', 'Das halbmondförmige Messer des Torcedors. Es schneidet das Deckblatt aus dem Blatt; neben dem Pflanzenleim ist es das einzige Werkzeug, das der Roller griffbereit hält.', '半月刀', '卷烟师使用的半月形刀，用来从烟叶上裁出外包叶。除了植物胶，这是工人手边唯一的工具。', 'التشافيتا', 'سكين «التورسيدور» الهلالي الشكل. به تُقطع الورقة الخارجية من الورقة الأم؛ وهو، مع الصمغ النباتي، الأداة الوحيدة التي يبقيها العامل في متناول يده.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'chaveta');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'capuchon', 'forme', 'capuchon|capuchons|cabeza', 'Capuchon', 'Le petit disque de cape qui ferme la tête du cigare, collé avec une colle végétale. On le tranche avant de fumer, sans aller trop profond : la cape se défait.', 'Cap', 'The small disc of wrapper that closes the head of the cigar, stuck down with vegetable glue. It is cut before smoking, not too deep, or the wrapper unravels.', 'Cabeza', 'El pequeño disco de capa que cierra la cabeza del puro, pegado con goma vegetal. Se corta antes de fumar, sin ir demasiado hondo: la capa se deshace.', 'Kopf', 'Das kleine Deckblattscheibchen, das den Kopf der Zigarre verschließt, mit Pflanzenleim geklebt. Man schneidet es vor dem Rauchen an, nicht zu tief, sonst löst sich das Deckblatt auf.', '烟帽', '封住雪茄头部的一小片外包叶，用植物胶粘合。抽之前将其切开，不宜切得太深，否则外包叶会散开。', 'غطاء الرأس', 'القرص الصغير من الورقة الخارجية الذي يغلق رأس السيجار ويُلصق بصمغ نباتي. يُقطع قبل التدخين دون التعمق كثيرًا، وإلا انفكّت الورقة.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'capuchon');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'bague', 'forme', 'bague|bagues|anilla', 'Bague', 'Le ruban de papier que porte le cigare, avec le nom de la marque. On le retire ou on le garde selon l''amateur ; sa présence ne prouve pas l''authenticité d''un cigare.', 'Band', 'The paper ribbon a cigar wears, carrying the brand name. Smokers remove it or keep it as they like; its presence does not prove that a cigar is genuine.', 'Anilla', 'La cinta de papel que lleva el puro, con el nombre de la marca. Se quita o se deja según el aficionado; su presencia no prueba que el puro sea auténtico.', 'Bauchbinde', 'Das Papierband, das die Zigarre trägt, mit dem Namen der Marke. Man nimmt es ab oder lässt es dran, wie man mag; sein Vorhandensein beweist nicht, dass eine Zigarre echt ist.', '烟标环', '雪茄上印有品牌名称的纸环。抽烟者可摘可留；有这个纸环，并不能证明雪茄是真品。', 'الحلقة الورقية', 'شريط الورق الذي يلفّ السيجار ويحمل اسم العلامة. يُنزع أو يُترك بحسب رغبة المدخّن؛ ووجوده لا يثبت أن السيجار أصلي.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'bague');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'cedre', 'conservation', 'cèdre espagnol|cedro|cèdre', 'Cèdre espagnol', 'Le bois des boîtes et des humidors. Ce n''est pas un vrai cèdre (Cedrela odorata), mais il boit l''humidité et la rend doucement, et son parfum accompagne le tabac sans le couvrir.', 'Spanish cedar', 'The wood of cigar boxes and humidors. It is not a true cedar (Cedrela odorata), but it takes up moisture and gives it back gently, and its scent accompanies the tobacco without covering it.', 'Cedro español', 'La madera de las cajas y los humidores. No es un cedro verdadero (Cedrela odorata), pero absorbe la humedad y la devuelve despacio, y su aroma acompaña al tabaco sin taparlo.', 'Spanische Zeder', 'Das Holz der Zigarrenkisten und Humidore. Es ist keine echte Zeder (Cedrela odorata), nimmt aber Feuchtigkeit auf und gibt sie sanft zurück, und sein Duft begleitet den Tabak, ohne ihn zu überdecken.', '西班牙雪松', '雪茄盒和保湿盒所用的木材。它并非真正的雪松（Cedrela odorata），但能吸收水分并缓缓释放，香气陪衬烟草而不掩盖它。', 'الأرز الإسباني', 'خشب علب السيجار وخزائن الترطيب. وهو ليس أرزًا حقيقيًا (Cedrela odorata)، لكنه يمتص الرطوبة ويردّها ببطء، ورائحته ترافق التبغ دون أن تغطيه.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'cedre');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'puro', 'atelier', 'puro|puros', 'Puro', 'En espagnol, simplement « cigare ». On parle aussi de puro quand toutes les feuilles d''un cigare viennent d''un même pays, comme dans un Cuban puro.', 'Puro', 'Simply "cigar" in Spanish. The word is also used when every leaf in a cigar comes from a single country, as in a Cuban puro.', 'Puro', 'Simplemente «cigarro» en español. También se dice puro cuando todas las hojas de un puro proceden de un mismo país, como en un puro cubano.', 'Puro', 'Im Spanischen schlicht „Zigarre“. Man spricht auch von einem Puro, wenn alle Blätter einer Zigarre aus einem einzigen Land stammen, wie bei einem Cuban Puro.', 'Puro（纯叶雪茄）', '西班牙语里就是“雪茄”。当一支雪茄的所有烟叶都来自同一个国家时，也称 puro，例如古巴纯叶雪茄。', 'بورو', 'في الإسبانية تعني ببساطة «سيجار». ويُستعمل اللفظ أيضًا حين تأتي كل أوراق السيجار من بلد واحد، كما في السيجار الكوبي الخالص.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'puro');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'assembleur', 'assemblage', 'assembleur|assembleurs|blender|master blender', 'Assembleur', 'Celui qui compose l''assemblage : il choisit les feuilles de la tripe, de la sous-cape et de la cape, et en règle les proportions. Son travail se juge cigare en main, au fil des essais.', 'Blender', 'The person who composes the blend: they choose the leaves of the filler, binder and wrapper and set the proportions. The work is judged with a cigar in hand, trial after trial.', 'Maestro de mezclas', 'Quien compone la mezcla: elige las hojas de la tripa, la subcapa y la capa y fija las proporciones. Su trabajo se juzga con el puro en la mano, prueba tras prueba.', 'Blender', 'Wer die Mischung zusammenstellt: Er wählt die Blätter für Einlage, Umblatt und Deckblatt und legt die Anteile fest. Seine Arbeit beurteilt man mit der Zigarre in der Hand, Probe um Probe.', '调配师', '负责调配的人：挑选叶芯、束叶和外包叶，并确定它们的比例。他的工作要靠手里的雪茄，一次次试验来检验。', 'خالط التبغ', 'من يضع التركيبة: يختار أوراق الحشوة والغلاف الداخلي والورقة الخارجية ويضبط نسبها. ويُحكم على عمله والسيجار في اليد، تجربةً بعد تجربة.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'assembleur');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'ring-gauge', 'forme', 'ring gauge', 'Calibre (ring gauge)', 'Le diamètre d''un cigare, mesuré en soixante-quatrièmes de pouce. Un calibre 50 fait 50/64 de pouce, soit environ 19,8 mm.', 'Ring gauge', 'The diameter of a cigar, measured in sixty-fourths of an inch. A ring gauge of 50 is 50/64 of an inch, about 19.8 mm.', 'Cepo (ring gauge)', 'El diámetro de un puro, medido en sesentaicuatroavos de pulgada. Un cepo 50 son 50/64 de pulgada, unos 19,8 mm.', 'Ringmaß', 'Der Durchmesser einer Zigarre, gemessen in Vierundsechzigstel Zoll. Ein Ringmaß von 50 sind 50/64 Zoll, etwa 19,8 mm.', '环径（ring gauge）', '雪茄的直径，以六十四分之一英寸为单位。环径50即50/64英寸，约19.8毫米。', 'القطر (ring gauge)', 'قطر السيجار مقيسًا بأجزاء من أربعة وستين من البوصة. فالقطر 50 يساوي 50/64 من البوصة، أي نحو 19.8 ملم.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'ring-gauge');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'robusto', 'forme', 'robusto|robustos', 'Robusto', 'Une vitole courte et épaisse : environ 12,5 cm pour un calibre autour de 50. Un format d''une heure de fumage environ.', 'Robusto', 'A short, thick vitola: about 12.5 cm (5 inches) with a ring gauge around 50. A format of roughly an hour''s smoking.', 'Robusto', 'Una vitola corta y gruesa: unos 12,5 cm con un cepo de alrededor de 50. Un formato de aproximadamente una hora de fumada.', 'Robusto', 'Eine kurze, dicke Vitola: etwa 12,5 cm bei einem Ringmaß um 50. Ein Format mit rund einer Stunde Rauchzeit.', 'Robusto（罗布图）', '短而粗的烟型：长约12.5厘米，环径约50。抽一支大约需要一小时。', 'روبوستو', 'حجم قصير وسميك: نحو 12.5 سم بقطر قريب من 50. وهو حجم يستغرق تدخينه ساعة تقريبًا.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'robusto');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'lancero', 'forme', 'lancero|lanceros', 'Lancero', 'Une vitole longue et fine : environ 19 cm pour un calibre autour de 38. Peu de tripe, donc une fumée dominée par la cape.', 'Lancero', 'A long, slender vitola: about 19 cm (7½ inches) with a ring gauge around 38. Little filler, so the smoke is led by the wrapper.', 'Lancero', 'Una vitola larga y fina: unos 19 cm con un cepo de alrededor de 38. Poca tripa, así que el humo lo conduce la capa.', 'Lancero', 'Eine lange, schlanke Vitola: etwa 19 cm bei einem Ringmaß um 38. Wenig Einlage, daher wird der Rauch vom Deckblatt geprägt.', 'Lancero（长枪型）', '细长的烟型：长约19厘米，环径约38。叶芯少，因此烟气以外包叶的味道为主。', 'لانسيرو', 'حجم طويل ونحيل: نحو 19 سم بقطر قريب من 38. حشوته قليلة، فيغلب على الدخان طعم الورقة الخارجية.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'lancero');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'torpedo', 'forme', 'torpedo|torpedos|torpédo', 'Torpedo', 'Un figurado à la tête pointue et au pied ouvert. À ne pas confondre avec le perfecto, fermé aux deux bouts.', 'Torpedo', 'A figurado with a pointed head and an open foot. Not to be confused with the perfecto, which is closed at both ends.', 'Torpedo', 'Un figurado de cabeza puntiaguda y pie abierto. No debe confundirse con el perfecto, cerrado por los dos extremos.', 'Torpedo', 'Ein Figurado mit spitzem Kopf und offenem Fuß. Nicht zu verwechseln mit dem Perfecto, das an beiden Enden geschlossen ist.', 'Torpedo（鱼雷型）', '头部尖、脚部开口的异形雪茄。别与两端都封闭的 perfecto 混淆。', 'توربيدو', 'سيجار «فيغورادو» ذو رأس مدبّب وقاعدة مفتوحة. ولا يُخلط بينه وبين «بيرفيكتو» المغلق من الطرفين.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'torpedo');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'churchill', 'forme', 'churchill|churchills', 'Churchill', 'Une vitole longue, environ 18 cm pour un calibre 47 (7 pouces). Elle porte le nom de l''homme d''État britannique, devenu une image du fumeur de cigare.', 'Churchill', 'A long vitola, about 18 cm (7 inches) with a ring gauge of 47. It carries the name of the British statesman, who became an image of the cigar smoker.', 'Churchill', 'Una vitola larga, de unos 18 cm (7 pulgadas) con cepo 47. Lleva el nombre del estadista británico, convertido en imagen del fumador de puros.', 'Churchill', 'Eine lange Vitola, etwa 18 cm (7 Zoll) bei Ringmaß 47. Sie trägt den Namen des britischen Staatsmanns, der zum Bild des Zigarrenrauchers wurde.', 'Churchill（丘吉尔型）', '长烟型，约18厘米（7英寸），环径47。名称取自那位英国政治家，他后来成了雪茄抽烟者的形象。', 'تشرشل', 'حجم طويل نحو 18 سم (7 بوصات) بقطر 47. يحمل اسم رجل الدولة البريطاني الذي صار صورة لمدخّن السيجار.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'churchill');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'tube', 'forme', 'tubo|tubos|cigare en tube|cigares en tube', 'Tube', 'Un cigare vendu dans son propre étui, en aluminium, en verre ou en bois. Il le protège des chocs et de l''air, mais ne remplace pas un humidor pour une longue garde.', 'Tubed cigar', 'A cigar sold in its own case, of aluminium, glass or wood. It protects the cigar from knocks and air, but does not replace a humidor for long storage.', 'Tubo', 'Un puro vendido en su propio estuche, de aluminio, vidrio o madera. Lo protege de los golpes y del aire, pero no sustituye a un humidor para una larga conservación.', 'Röhrchen (Tubo)', 'Eine Zigarre, die in einer eigenen Hülse aus Aluminium, Glas oder Holz verkauft wird. Sie schützt vor Stößen und Luft, ersetzt aber für die lange Lagerung keinen Humidor.', '管装雪茄', '装在专用管中出售的雪茄，管子由铝、玻璃或木头制成。它能防撞和隔绝空气，但长期存放时不能代替保湿盒。', 'السيجار في أنبوب', 'سيجار يُباع في أنبوبه الخاص من الألمنيوم أو الزجاج أو الخشب. يحميه من الصدمات والهواء، لكنه لا يغني عن خزانة الترطيب في الحفظ الطويل.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'tube');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'cigarillo', 'forme', 'cigarillo|cigarillos', 'Cigarillo', 'Un petit cigare fin, qui se fume en quelques minutes. Il se distingue de la cigarette par son tabac en feuille et de la vitole classique par sa taille.', 'Cigarillo', 'A small, slim cigar that is smoked in a few minutes. It differs from a cigarette by its leaf tobacco, and from a classic vitola by its size.', 'Cigarrillo (puro pequeño)', 'Un puro pequeño y fino que se fuma en pocos minutos. Se distingue del cigarrillo por su tabaco en hoja y de la vitola clásica por su tamaño.', 'Zigarillo', 'Eine kleine, schlanke Zigarre, die in wenigen Minuten geraucht ist. Von der Zigarette unterscheidet sie sich durch den Blatttabak, von der klassischen Vitola durch die Größe.', '小雪茄（cigarillo）', '一种细小的雪茄，几分钟即可抽完。与香烟的区别在于用的是整叶烟草，与传统烟型的区别在于尺寸。', 'سيجاريلو', 'سيجار صغير ونحيل يُدخَّن في دقائق قليلة. يختلف عن السيجارة بتبغه الورقي، وعن الحجم التقليدي بصغر حجمه.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'cigarillo');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'tapado', 'feuille', 'tapado|sous voile|sous toile', 'Tapado', 'Du tabac cultivé sous un voile de coton qui tamise le soleil. Les feuilles y sont plus fines et plus claires ; c''est la culture classique des capes.', 'Tapado', 'Tobacco grown under a cotton cloth that filters the sun. The leaves come out thinner and lighter; it is the classic way of growing wrappers.', 'Tapado', 'Tabaco cultivado bajo una tela de algodón que filtra el sol. Las hojas salen más finas y claras; es el cultivo clásico de las capas.', 'Tapado', 'Tabak, der unter einem Baumwolltuch wächst, das die Sonne filtert. Die Blätter werden dünner und heller; es ist die klassische Anbauweise für Deckblätter.', '遮荫栽培（tapado）', '种在棉布遮罩下、阳光被过滤的烟草。叶片更薄更浅；这是外包叶的传统种植方式。', 'التاباد', 'تبغ يُزرع تحت قماش قطني يرشّح الشمس. تخرج أوراقه أرقّ وأفتح؛ وهي الطريقة التقليدية لزراعة الأوراق الخارجية.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'tapado');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'plein-soleil', 'feuille', 'plein soleil|à plein soleil|sun grown|capa de sol', 'Plein soleil', 'Du tabac cultivé sans voile, en plein soleil. Les feuilles sont plus épaisses et plus puissantes ; on les destine surtout à la tripe et à certaines capes.', 'Sun-grown', 'Tobacco grown without cloth, in full sun. The leaves are thicker and stronger; they are used mostly for filler and for certain wrappers.', 'Pleno sol', 'Tabaco cultivado sin tela, a pleno sol. Las hojas son más gruesas y fuertes; se destinan sobre todo a la tripa y a ciertas capas.', 'Sonnenanbau', 'Tabak, der ohne Tuch in voller Sonne wächst. Die Blätter sind dicker und kräftiger; man verwendet sie vor allem für die Einlage und für manche Deckblätter.', '露天栽培', '不加遮罩、在烈日下种植的烟草。叶片更厚更浓烈，多用于叶芯，也用于某些外包叶。', 'الزراعة تحت الشمس', 'تبغ يُزرع دون قماش تحت أشعة الشمس الكاملة. أوراقه أسمك وأقوى، وتُستعمل في الحشوة خصوصًا وفي بعض الأوراق الخارجية.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'plein-soleil');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'moho-azul', 'feuille', 'moho azul|blue mold|mildiou du tabac', 'Moho azul', 'Le mildiou du tabac, une maladie du plant causée par un champignon apparenté (Peronospora). Il frappe les cultures sur pied et n''a rien à voir avec les moisissures qui guettent un cigare mal gardé.', 'Blue mould (moho azul)', 'Tobacco downy mildew, a disease of the growing plant caused by a fungus-like organism (Peronospora). It attacks standing crops and has nothing to do with the moulds that threaten a badly stored cigar.', 'Moho azul', 'El mildiu del tabaco, una enfermedad de la planta causada por un organismo parecido a un hongo (Peronospora). Ataca los cultivos en pie y nada tiene que ver con los mohos que amenazan a un puro mal conservado.', 'Blauschimmel (Moho azul)', 'Der Blauschimmel des Tabaks, eine Pflanzenkrankheit, die ein pilzähnlicher Organismus (Peronospora) auslöst. Er befällt die Kulturen auf dem Feld und hat nichts mit dem Schimmel zu tun, der eine schlecht gelagerte Zigarre bedroht.', '蓝霉病（moho azul）', '烟草霜霉病，由一种类似真菌的生物（Peronospora）引起的植株病害。它危害田间的烟株，与存放不当的雪茄上滋生的霉菌毫无关系。', 'العفن الأزرق', 'عفن التبغ الزغبي، مرض يصيب النبتة سببه كائن شبيه بالفطريات (Peronospora). يضرب المحاصيل القائمة في الحقل، ولا علاقة له بالعفن الذي يهدد السيجار سيّئ الحفظ.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'moho-azul');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'humidor', 'conservation', 'humidor|humidors', 'Humidor', 'Une boîte, une armoire ou une pièce qui tient les cigares à une humidité stable, autour de 65 à 72 % et de 16 à 21 °C. Les chiffres varient selon les maisons et les amateurs.', 'Humidor', 'A box, cabinet or room that keeps cigars at a steady humidity, around 65 to 72% and 16 to 21 °C. The figures vary between makers and smokers.', 'Humidor', 'Una caja, armario o sala que mantiene los puros a una humedad estable, de 65 a 72 % y de 16 a 21 °C aproximadamente. Las cifras varían según las casas y los aficionados.', 'Humidor', 'Eine Kiste, ein Schrank oder ein Raum, der Zigarren bei gleichmäßiger Feuchtigkeit hält, etwa 65 bis 72 % und 16 bis 21 °C. Die Zahlen schwanken je nach Haus und Raucher.', '雪茄保湿盒（humidor）', '一种盒子、柜子或房间，使雪茄保持稳定的湿度，约65%至72%，温度16至21摄氏度。各品牌和抽烟者所取数值不一。', 'خزانة الترطيب', 'صندوق أو خزانة أو غرفة تحفظ السيجار عند رطوبة ثابتة، نحو 65 إلى 72٪ ودرجة حرارة 16 إلى 21 مئوية. وتختلف الأرقام بين الدور والمدخّنين.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'humidor');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'hygrometre', 'conservation', 'hygromètre|hygromètres', 'Hygromètre', 'L''instrument qui mesure l''humidité d''un humidor. Les modèles à aiguille se dérèglent : on les vérifie avec un test au sel, qui doit afficher environ 75 % après plusieurs heures.', 'Hygrometer', 'The instrument that measures the humidity of a humidor. Dial models drift out of true: they are checked with a salt test, which should read about 75% after several hours.', 'Higrómetro', 'El instrumento que mide la humedad de un humidor. Los de aguja se desajustan: se comprueban con una prueba de la sal, que debe marcar cerca de un 75 % tras varias horas.', 'Hygrometer', 'Das Instrument, das die Feuchtigkeit eines Humidors misst. Zeigermodelle gehen falsch: Man prüft sie mit einem Salztest, der nach mehreren Stunden etwa 75 % anzeigen sollte.', '湿度计', '测量保湿盒湿度的仪器。指针式容易失准，可用盐测法校验：数小时后读数应约为75%。', 'مقياس الرطوبة', 'الأداة التي تقيس رطوبة خزانة الترطيب. والنماذج ذات المؤشر تفقد دقتها، وتُفحص باختبار الملح الذي ينبغي أن يشير إلى نحو 75٪ بعد ساعات.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'hygrometre');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'plume', 'conservation', 'plumage|bloom', 'Plume (bloom)', 'Un fin voile cristallin et blanc qui apparaît sur la cape après une longue garde : des huiles et des sucres remontés à la surface. Selon les amateurs, il part au doigt, sans odeur ; la moisissure, elle, est duveteuse, colorée et sent le moisi.', 'Bloom', 'A fine, white, crystalline film that can appear on the wrapper after long ageing: oils and sugars risen to the surface. Smokers say it brushes off, without smell; mould, by contrast, is fuzzy, coloured and smells musty.', 'Plume (bloom)', 'Un fino velo cristalino y blanco que puede aparecer en la capa tras una larga guarda: aceites y azúcares subidos a la superficie. Según los aficionados, se quita con el dedo y no huele; el moho, en cambio, es velloso, coloreado y huele a humedad.', 'Bloom (Tabakreif)', 'Ein feiner, weißer, kristalliner Schleier, der nach langer Lagerung auf dem Deckblatt erscheinen kann: Öle und Zucker, die an die Oberfläche gestiegen sind. Raucher sagen, er lasse sich abwischen und rieche nicht; Schimmel dagegen ist flaumig, farbig und riecht muffig.', '烟霜（bloom）', '长期存放后外包叶上可能出现的一层白色细晶体薄膜，是油脂和糖分渗到表面所致。据抽烟者说，它一抹即去且无异味；而霉菌则呈绒毛状、带颜色，并有霉味。', 'الزهر (bloom)', 'غشاء بلوري أبيض رقيق قد يظهر على الورقة الخارجية بعد حفظ طويل: زيوت وسكريات صعدت إلى السطح. يقول المدخّنون إنه يزول بالمسح ولا رائحة له؛ أما العفن فزغبي ملوّن ورائحته عفنة.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'plume');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'regulateur-humidite', 'conservation', 'régulateur d''humidité|pack d''humidité|sachet d''humidité', 'Régulateur d''humidité', 'Un sachet à solution saline qui rend ou absorbe l''humidité pour tenir un taux visé (65, 69 ou 72 %). Il remplace l''éponge et l''eau distillée, sans dispenser de surveiller l''humidor.', 'Humidity pack', 'A saline-solution pouch that gives off or absorbs moisture to hold a target level (65, 69 or 72%). It replaces the sponge and distilled water, but does not excuse you from watching the humidor.', 'Regulador de humedad', 'Una bolsita de solución salina que cede o absorbe humedad para mantener un nivel fijado (65, 69 o 72 %). Sustituye a la esponja y al agua destilada, sin dispensar de vigilar el humidor.', 'Feuchtigkeitsregler', 'Ein Beutel mit Salzlösung, der Feuchtigkeit abgibt oder aufnimmt, um einen Zielwert (65, 69 oder 72 %) zu halten. Er ersetzt Schwamm und destilliertes Wasser, entbindet aber nicht davon, den Humidor zu beobachten.', '保湿包', '装有盐溶液的小包，通过释放或吸收水分，把湿度维持在设定值（65%、69%或72%）。它取代了海绵和蒸馏水，但并不意味着可以不再留意保湿盒。', 'كيس ضبط الرطوبة', 'كيس يحتوي محلولًا ملحيًا يطلق الرطوبة أو يمتصها ليثبّت مستوى مستهدفًا (65 أو 69 أو 72٪). يحلّ محل الإسفنجة والماء المقطّر، لكنه لا يعفي من مراقبة الخزانة.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'regulateur-humidite');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'tirage', 'degustation', 'tirage|tirages', 'Tirage', 'La résistance de l''air quand on aspire au cigare. Trop serré, il fatigue ; trop lâche, la fumée chauffe et file. Il dépend du roulage et de l''humidité autant que du tabac.', 'Draw', 'The resistance to the air when you pull on a cigar. Too tight, it tires you; too loose, the smoke runs hot and fast. It depends on the rolling and the humidity as much as on the tobacco.', 'Tiro', 'La resistencia del aire al aspirar el puro. Demasiado apretado, cansa; demasiado suelto, el humo se calienta y se escapa. Depende del liado y de la humedad tanto como del tabaco.', 'Zug', 'Der Widerstand der Luft, wenn man an der Zigarre zieht. Zu fest ermüdet er; zu locker wird der Rauch heiß und zieht schnell durch. Er hängt vom Rollen und von der Feuchtigkeit ab, nicht nur vom Tabak.', '抽吸阻力（tirage）', '吸烟时空气通过雪茄的阻力。太紧让人吃力；太松则烟气发烫、流得过快。它既取决于烟叶，也取决于卷制和湿度。', 'السحب', 'مقاومة الهواء عند الشفط من السيجار. إن كان محكمًا أرهق، وإن كان رخوًا سخن الدخان وانساب بسرعة. ويتوقف على اللفّ والرطوبة بقدر ما يتوقف على التبغ.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'tirage');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'cendre', 'degustation', 'cendre|cendres', 'Cendre', 'Ce que laisse le cigare en brûlant. Sa tenue dit surtout comment le cigare est roulé et brûle ; ce n''est pas une preuve de qualité à elle seule.', 'Ash', 'What a cigar leaves as it burns. How well it holds says mostly how the cigar is rolled and burns; it is not proof of quality on its own.', 'Ceniza', 'Lo que deja el puro al arder. Su firmeza dice sobre todo cómo está liado y cómo arde; por sí sola no prueba la calidad.', 'Asche', 'Was die Zigarre beim Abbrennen hinterlässt. Wie fest sie hält, sagt vor allem etwas über das Rollen und das Abbrennen; ein Qualitätsbeweis ist sie allein nicht.', '烟灰', '雪茄燃烧后留下的东西。烟灰是否牢固，主要反映卷制和燃烧情况，本身并不能证明品质。', 'الرماد', 'ما يتركه السيجار وهو يحترق. وتماسكه يدلّ أساسًا على طريقة لفّه واحتراقه؛ وهو وحده ليس دليلًا على الجودة.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'cendre');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'retro-olfaction', 'degustation', 'rétro-olfaction|rétrolfaction|rétro-hale|retrohale', 'Rétro-olfaction', 'Faire remonter la fumée par le nez en expirant, sans l''avaler. C''est là que les arômes se perçoivent nettement ; elle surprend le débutant.', 'Retrohale', 'Letting the smoke rise through the nose as you exhale, without inhaling it. This is where aromas come through clearly; it surprises the beginner.', 'Retronasal (retrohale)', 'Dejar subir el humo por la nariz al exhalar, sin tragarlo. Ahí es donde los aromas se perciben con nitidez; sorprende al principiante.', 'Retronasales Riechen (Retrohale)', 'Den Rauch beim Ausatmen durch die Nase aufsteigen lassen, ohne ihn zu inhalieren. Hier nimmt man die Aromen deutlich wahr; Anfänger überrascht das.', '鼻腔回呼（retrohale）', '呼气时让烟气从鼻腔升起，而不吸入肺中。香气在这里感受得很清楚；初学者常会感到意外。', 'الشمّ الراجع', 'ترك الدخان يصعد من الأنف عند الزفير دون ابتلاعه. وهنا تتجلى الروائح بوضوح؛ وقد يفاجئ المبتدئ.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'retro-olfaction');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'coupe-cigare', 'degustation', 'coupe-cigare|coupe-cigares|guillotine|cigar cutter', 'Coupe-cigare', 'L''outil qui ouvre la tête du cigare : guillotine à une ou deux lames, perforateur (punch) ou coupe en V. On tranche peu : trop profond, la cape se défait.', 'Cigar cutter', 'The tool that opens the head of the cigar: a single- or double-blade guillotine, a punch or a V-cut. Cut little: too deep and the wrapper unravels.', 'Cortapuros', 'La herramienta que abre la cabeza del puro: guillotina de una o dos hojas, perforador (punch) o corte en V. Se corta poco: demasiado hondo, la capa se deshace.', 'Zigarrenschneider', 'Das Werkzeug, das den Kopf der Zigarre öffnet: Guillotine mit einer oder zwei Klingen, Punch oder V-Schnitt. Man schneidet wenig: zu tief, und das Deckblatt löst sich.', '雪茄剪', '用来开启雪茄头部的工具：单刃或双刃断头式、打孔式，或V形切口。切得要浅，切深了外包叶会散开。', 'قاطع السيجار', 'الأداة التي تفتح رأس السيجار: مقصلة بشفرة أو شفرتين، أو مثقب (punch)، أو قطع على شكل V. يُقطع القليل فقط، فإن عمّق القطع انفكّت الورقة الخارجية.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'coupe-cigare');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'pre-allumage', 'degustation', 'pré-allumage|prechauffer le pied|préchauffer le pied|toaster', 'Pré-allumage', 'Chauffer le pied du cigare à la flamme, sans la poser, jusqu''à ce qu''il brunisse légèrement, puis l''allumer en tirant doucement. Il assure un allumage régulier.', 'Toasting the foot', 'Warming the foot of the cigar over a flame, without touching it, until it browns slightly, then lighting it with gentle puffs. It gives an even light.', 'Calentar el pie', 'Calentar el pie del puro a la llama, sin tocarlo, hasta que se oscurece un poco, y encenderlo después tirando con suavidad. Asegura un encendido uniforme.', 'Vorwärmen des Fußes', 'Den Fuß der Zigarre über der Flamme erwärmen, ohne ihn zu berühren, bis er leicht bräunt, dann mit sanften Zügen anzünden. So brennt sie gleichmäßig an.', '预热烟脚', '将火焰靠近雪茄脚部加热但不接触，直到略微变褐，再轻轻吸气点燃。这样能让点燃均匀。', 'تسخين القاعدة', 'تسخين قاعدة السيجار على اللهب دون ملامسته حتى تسمرّ قليلًا، ثم إشعاله بسحب هادئ. وبذلك يشتعل بانتظام.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'pre-allumage');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'tiers', 'degustation', 'tiers du cigare|premier tiers|dernier tiers|tercio', 'Les tiers', 'Un cigare se fume en trois parties, que les amateurs lisent comme trois temps. La force et les arômes évoluent souvent du début à la fin ; la dernière partie s''abandonne quand elle devient amère.', 'Thirds', 'A cigar is smoked in three parts, which smokers read as three movements. Strength and aromas often change from start to end; the last part is put down once it turns bitter.', 'Tercios', 'Un puro se fuma en tres partes, que los aficionados leen como tres tiempos. La fuerza y los aromas suelen evolucionar del principio al final; la última parte se deja cuando se vuelve amarga.', 'Drittel', 'Eine Zigarre raucht man in drei Abschnitten, die Raucher als drei Sätze lesen. Stärke und Aromen verändern sich oft von Anfang bis Ende; das letzte Stück legt man weg, wenn es bitter wird.', '三段式', '一支雪茄分三段抽，爱抽雪茄的人把它当作三个乐章来品味。力度和香气常从头到尾变化；末段一旦变苦就放下。', 'الأثلاث', 'يُدخَّن السيجار على ثلاثة أجزاء يقرؤها المدخّنون كثلاث حركات. وغالبًا ما تتغير القوة والروائح من البداية إلى النهاية؛ ويُترك الجزء الأخير حين يصير مرًّا.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'tiers');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'force-et-corps', 'degustation', 'force et corps|corps et force', 'Force et corps', 'Deux choses distinctes. La force est l''effet de la nicotine ; le corps est la plénitude de la fumée en bouche. Un cigare peut être plein sans être fort, et inversement.', 'Strength and body', 'Two separate things. Strength is the effect of nicotine; body is the fullness of the smoke in the mouth. A cigar can be full-bodied without being strong, and the reverse.', 'Fuerza y cuerpo', 'Dos cosas distintas. La fuerza es el efecto de la nicotina; el cuerpo es la plenitud del humo en la boca. Un puro puede tener cuerpo sin ser fuerte, y al revés.', 'Stärke und Körper', 'Zwei verschiedene Dinge. Die Stärke ist die Wirkung des Nikotins; der Körper ist die Fülle des Rauchs im Mund. Eine Zigarre kann vollmundig sein, ohne stark zu sein, und umgekehrt.', '力度与醇厚度', '两件不同的事。力度是尼古丁的作用；醇厚度是烟气在口中的丰满感。一支雪茄可以醇厚而不烈，反之亦然。', 'القوة والجسم', 'أمران مختلفان. القوة هي أثر النيكوتين، والجسم هو امتلاء الدخان في الفم. قد يكون السيجار ممتلئًا دون أن يكون قويًا، والعكس صحيح.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'force-et-corps');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'persistance', 'degustation', 'persistance aromatique|persistance en bouche', 'Persistance aromatique', 'Le temps pendant lequel les arômes restent en bouche après une bouffée. C''est ce que les dégustateurs appellent aussi la finale.', 'Finish', 'How long the aromas stay in the mouth after a puff. It is what tasters also call the finish.', 'Persistencia aromática', 'El tiempo que los aromas permanecen en la boca tras una calada. Es lo que los catadores llaman también el final.', 'Nachhall', 'Wie lange die Aromen nach einem Zug im Mund bleiben. Verkoster nennen das auch den Abgang.', '余味', '吸一口后香气在口中停留的时间，品鉴者也称之为余味。', 'البقاء العطري', 'المدة التي تبقى فيها الروائح في الفم بعد نفَس. وهي ما يسمّيه المتذوقون أيضًا الختام.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'persistance');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'edicion-regional', 'marche', 'edición regional|ediciones regionales|edicion regional', 'Edición Regional', 'Un cigare Habanos réservé à un marché ou à une région, produit pour son distributeur. Il ne se trouve, en principe, que là.', 'Regional Edition', 'A Habanos cigar reserved for one market or region, produced for its distributor. In principle it is found only there.', 'Edición Regional', 'Un puro Habanos reservado a un mercado o una región, producido para su distribuidor. En principio solo se encuentra allí.', 'Edición Regional', 'Eine Habanos-Zigarre, die einem Markt oder einer Region vorbehalten ist und für deren Vertrieb hergestellt wird. Sie ist im Prinzip nur dort erhältlich.', '地区限定版（Edición Regional）', '专供某个市场或地区的Habanos雪茄，为当地经销商生产。原则上只能在当地买到。', 'الإصدار الإقليمي', 'سيجار «هابانوس» مخصص لسوق أو منطقة، يُنتج لموزّعها. ولا يوجد، من حيث المبدأ، إلا هناك.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'edicion-regional');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'edicion-limitada', 'marche', 'edición limitada|ediciones limitadas|edicion limitada', 'Edición Limitada', 'Une série annuelle de Habanos, dont la cape, selon Habanos, a vieilli au moins deux ans avant le roulage. Elle porte l''année de sortie sur la bague.', 'Limited Edition', 'An annual series of Habanos whose wrapper, according to Habanos, has aged at least two years before rolling. It carries the year of release on the band.', 'Edición Limitada', 'Una serie anual de Habanos cuya capa, según Habanos, ha envejecido al menos dos años antes de liar. Lleva el año de salida en la anilla.', 'Edición Limitada', 'Eine jährliche Serie von Habanos, deren Deckblatt laut Habanos vor dem Rollen mindestens zwei Jahre gereift ist. Sie trägt das Erscheinungsjahr auf dem Bauchband.', '限量版（Edición Limitada）', 'Habanos每年推出的系列，据Habanos称，其外包叶在卷制前至少陈放两年。烟标环上印有发行年份。', 'الإصدار المحدود', 'سلسلة سنوية من «هابانوس» ورقتها الخارجية، بحسب «هابانوس»، معتّقة سنتين على الأقل قبل اللفّ. وتحمل سنة الإصدار على الحلقة.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'edicion-limitada');

INSERT INTO `lexique` (`id`, `categorie`, `variantes`, `terme`, `definition`, `terme_en`, `definition_en`, `terme_es`, `definition_es`, `terme_de`, `definition_de`, `terme_zh`, `definition_zh`, `terme_ar`, `definition_ar`)
SELECT 'bande-garantie', 'marche', 'bande de garantie|sceau de garantie|warranty seal', 'Bande de garantie', 'Sur une boîte de Habanos, la bande portant les mentions de contrôle. Elle aide à vérifier l''origine, sans suffire : des bandes elles-mêmes sont contrefaites.', 'Warranty seal', 'On a box of Habanos, the strip carrying the control marks. It helps to check the origin, but does not suffice: the strips themselves are counterfeited.', 'Banda de garantía', 'En una caja de Habanos, la banda con las marcas de control. Ayuda a comprobar el origen, pero no basta: hay bandas falsificadas.', 'Garantiesiegel', 'Auf einer Habanos-Kiste der Streifen mit den Kontrollvermerken. Er hilft, die Herkunft zu prüfen, genügt aber nicht: Auch die Streifen selbst werden gefälscht.', '防伪封条', 'Habanos雪茄盒上印有检验标记的封条。它有助于核对来源，但并不足够：封条本身也有被仿造的。', 'شريط الضمان', 'على علبة «هابانوس»، الشريط الذي يحمل علامات المراقبة. يساعد على التحقق من الأصل لكنه لا يكفي، فالأشرطة نفسها تُزوَّر.'
 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `lexique` WHERE `id` = 'bande-garantie');

INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `maj`)
SELECT 'lexique', l.`id`, f.champ, g.lang, SHA1(IF(f.champ = 'terme', l.`terme`, l.`definition`)), 'machine', NOW()
  FROM `lexique` l
  JOIN (SELECT 'terme' champ UNION ALL SELECT 'definition') f
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') g
 WHERE l.`id` IN ('fermentation', 'despalillo', 'casa-de-tabaco', 'tripe-longue', 'hecho-a-mano', 'chaveta', 'capuchon', 'bague', 'cedre', 'puro', 'assembleur', 'ring-gauge', 'robusto', 'lancero', 'torpedo', 'churchill', 'tube', 'cigarillo', 'tapado', 'plein-soleil', 'moho-azul', 'humidor', 'hygrometre', 'plume', 'regulateur-humidite', 'tirage', 'cendre', 'retro-olfaction', 'coupe-cigare', 'pre-allumage', 'tiers', 'force-et-corps', 'persistance', 'edicion-regional', 'edicion-limitada', 'bande-garantie')
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `statut` = 'machine', `maj` = NOW();

DELETE FROM `moderation_log` WHERE `acteur_nom` = 'migration 315';
INSERT INTO `moderation_log` (`acteur_id`, `acteur_nom`, `portee`, `action`, `cible_type`, `cible_id`, `detail`)
VALUES (NULL, 'migration 315', 'systeme', 'lexique_enrichi', 'systeme', 0, 'Lexique : 36 termes ajoutes (20 -> 56)');

-- Contrôle : des 1 partout.
SELECT
  (SELECT COUNT(*) FROM `lexique`) = 56 AS `termes`,
  (SELECT COUNT(*) FROM `lexique` WHERE `terme_ar` IS NULL OR `definition_zh` IS NULL OR `definition_de` IS NULL) = 0 AS `traduits`;
